// --- API Link Helper ---

function getApiUrl(endpoint) {
    const isModular = (typeof current_chall === 'number' || !isNaN(current_chall));
    const segment = isModular ? "" : `/${current_chall}`;
    return `${base_url}${segment}/${endpoint}`;
}

// --- Request Helpers ---

async function get_xrefs_from(func) {
    const url = getApiUrl("get_xrefs_from");
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({ 'name': func, 'token': id })
        });
        if (!response.ok) return;
        const xref = await response.json();

        if (!Object.keys(xref).length) return;
        let msg = `<ul id='x_from' style='list-style:none;font-size:16px'>Xrefs from:`;
        for (let i in xref) {
            msg += `<li><a href="./?function=${i}" onclick="push_function_history('${func_to_download}', null)">${xref[i]}</a></li>`;
        }
        msg += `</ul>`;

        const target = document.getElementById(func);
        if (target) target.insertAdjacentHTML('afterend', msg);
    } catch (e) { console.error(e); }
}

async function get_xrefs_to(func) {
    const url = getApiUrl("get_xrefs_to");
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({ 'name': func, 'token': id })
        });
        if (!response.ok) return;
        const xref = await response.json();

        if (!Object.keys(xref).length) return;
        let msg = `<ul id='x_to' style='list-style:none;font-size:16px'>Xrefs to:`;
        for (let i in xref) {
            msg += `<li><a href="./?function=${i}" onclick="push_function_history('${func_to_download}', null)">${xref[i]}</a></li>`;
        }
        msg += `</ul>`;

        const target = document.getElementById(func);
        if (target) target.insertAdjacentHTML('afterend', msg);
    } catch (e) { console.error(e); }
}

async function downloadCallGraph() {
    const url = getApiUrl("getCallGraph");
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({ 'name': 'callgraph' })
        });
        if (!response.ok) return;
        json_callgraph = await response.json();
        if (typeof buildCallgraph === 'function') buildCallgraph();
    } catch (e) { console.error(e); }
    return 0;
}

async function downloadCFG(func) {
    const url = getApiUrl("getCFG");
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({ 'name': func, 'token': id })
        });
        if (!response.ok) return;
        json_cfg = await response.json();
        if (typeof CFGbuilder === 'function') CFGbuilder(json_cfg, func);
        return json_cfg;
    } catch (e) { console.error(e); return null; }
}

function send_results(data) {
    const url = getApiUrl("getmethod/");
    data["fcn_name"] = func_to_download;
    const endpoint = `${url}${id};${JSON.stringify(data)}`;
    fetch(endpoint).catch(err => console.error(err));
}

async function downloadData() {
    const url = getApiUrl("getevents/");
    const params = new URLSearchParams({ id: id, fcn_name: func_to_download });
    try {
        const response = await fetch(`${url}?${params.toString()}`);
        if (!response.ok) return;
        const data = await response.json();
        myData = data;
        if (typeof restore_graph_comments === 'function') restore_graph_comments(data);
        if (typeof demo === 'function') demo();
    } catch (e) { console.error(e); }
}

// --- Graph Logic ---

function isComment(addr) {
    const tokens = document.querySelectorAll(`span.token.generic`);
    return Array.from(tokens).some(t => t.id === addr && t.textContent.includes("#"));
}

function removeGraph() {
    const svgG = document.querySelector("svg > g");
    if (svgG) svgG.remove();
}

function CFGbuilder(json_cfg, func_name) {
    Object.keys(json_cfg[func_name + "_bbs"]).forEach(state => {
        cfg[state] = {
            asm: json_cfg[func_name + "_bbs"][state],
            obfuscated: "------- ----\n"
        };
    });

    g = new dagreD3.graphlib.Graph().setGraph({});
    Object.keys(cfg).forEach(state => {
        let value = cfg[state];
        value.labelType = "html";
        value.label = `<pre><code id='${state}' class='language-nasm'>${value.asm}</code></pre>`;
        value.rx = value.ry = 5;
        value.id = state;
        g.setNode(state, value);
    });

    let edges = json_cfg[func_name + "_edges"]["edges"];
    cfg_edges = edges;

    let binary_edges = {};
    const challId = parseInt(current_chall);
    if (current_chall === "first_chall" || challId === 1) binary_edges = first_binary_edges;
    else if (current_chall === "seventh_chall" || challId === 7) binary_edges = second_binary_edges;
    else if (current_chall === "fourth_chall" || challId === 4) binary_edges = fourth_binary_edges;

    edges.forEach(e => {
        let options = { label: "" };
        if (func_name in binary_edges) {
            let branch = binary_edges[func_name][e[0]];
            if (branch && 't' in branch && branch['t'] !== branch['f']) {
                if (e[1] === branch['t']) options.style = "stroke: #00ff00; stroke-width: 4px; fill: none";
                else if (e[1] === branch['f']) options.style = "stroke: #f66; stroke-width: 4px; fill: none";
            }
        }
        g.setEdge(e[0], e[1], options);
    });

    render = new dagreD3.render();
    let svg = d3.select("svg");
    let inner = svg.append("g");

    zoom = d3.zoom().on("zoom", () => inner.attr("transform", d3.event.transform));
    svg.call(zoom);
    render(inner, g);

    svg.attr('width', 2000).attr('height', 1024);
    d3.select('svg').transition().duration(200).call(zoom.transform, d3.zoomIdentity.translate(400, 200).scale(0.5));
    if (typeof myPrism === 'function') myPrism(-1);
    downloadData();
}

function buildCallgraph() {
    for (let node of json_callgraph['nodes']) {
        callgraph[node[0]] = { label: node[1], rx: 5, ry: 5 };
    }

    call_g = new dagreD3.graphlib.Graph().setGraph({});
    Object.keys(callgraph).forEach(state => call_g.setNode(state, callgraph[state]));
    json_callgraph['edges'].forEach(e => call_g.setEdge(e[0], e[1], { label: "" }));

    call_render = new dagreD3.render();
    let svg = d3.select("svg");
    let inner = svg.append("g");

    call_zoom = d3.zoom().on("zoom", () => inner.attr("transform", d3.event.transform));
    svg.call(call_zoom);
    call_render(inner, call_g);

    svg.attr('width', 1600).attr('height', 1024);
}

function getBBbyAddress(addr) {
    let found;
    Object.keys(cfg).forEach(state => {
        const spans = document.querySelectorAll(`code[id="${state}"] span.token.address`);
        if (Array.from(spans).some(s => s.textContent.includes(addr))) found = state;
    });
    return found;
}

function cfg_getBBbyAddress(addr) {
    return Object.keys(cfg).find(state => cfg[state].asm.includes(addr + ":"));
}

function cfg_getBBbyString(s) {
    return Object.keys(cfg).filter(state => cfg[state].asm.includes(s));
}

function scrollToAddress(addr, enumType) {
    send_results({
        timestamp: Date.now(),
        event: scrollEventsEnum.properties[enumType].name,
        element: addr
    });
    const bb = getBBbyAddress(addr);
    if (!bb) return;
    destination = bb;
    const x = g._nodes[bb].x, y = g._nodes[bb].y;
    d3.select('svg').transition().duration(400).call(zoom.transform, d3.zoomIdentity.translate(-x + 500, -y + 200).scale(1));
}

function selected(elem) {
    if (elem && bbCache !== elem.id) {
        bbCache = elem.id;
        send_results({ timestamp: Date.now(), event: 'mouseover', element: elem.id });
        if (typeof obfuscate === 'function') obfuscate(elem.id);
    }
}

function follow(addr, ex_addr, enumType) {
    myHistory = ex_addr;
    const r = /0x[A-Za-z0-9]+/;
    if (addr.length > 5 && addr.match(r) && addr.match(r)[0] === addr) {
        scrollToAddress(addr, enumType);
    } else {
        alert("You cannot follow it");
    }
}

function cfg_comment(codeId, tokenAddress) {
    let r = prompt("insert comment");
    if (!r) return;
    if (r.length > 38) r = r.substring(0, 38);

    send_results({
        timestamp: Date.now(),
        event: 'comment',
        element: tokenAddress.querySelector('span')?.id || tokenAddress.id,
        value: r
    });

    const addr = tokenAddress.innerText.replace(":", "");
    cfg[codeId].asm = cfg[codeId].asm.replace(addr, `# ${r}\n${addr}`);
    cfg[codeId].label = cfg[codeId].label.replace(addr, `# ${r}\n${addr}`);

    removeGraph();
    graphRender(codeId);
}

function on_pause() {
    send_results({ timestamp: Date.now(), event: 'pause', element: '', value: '' });
}

function rename_func(addr_id) {
    const value = prompt("Insert a new function name");
    if (!value || all_the_functions.includes(value)) {
        if (value) alert("Name already in use");
        return;
    }

    const spans = document.querySelectorAll(`span[id="${addr_id}"].token.generic`);
    spans.forEach(span => {
        const text = span.innerText;
        if (text.includes("call")) {
            const func_addr = text.replace("call ", "").trim();
            send_results({ timestamp: Date.now(), event: 'func_rename', element: func_addr, value: value });

            document.querySelectorAll('span.token.number').forEach(s => {
                if (s.innerText === func_addr) {
                    s.innerText = value;
                    const bbId = s.closest('code')?.id;
                    if (bbId) {
                        cfg[bbId].asm = cfg[bbId].asm.replace(new RegExp(func_addr, 'g'), value);
                        cfg[bbId].label = cfg[bbId].label.replace(new RegExp(func_addr, 'g'), value);
                    }
                }
            });
        }
    });
}

function rename_sidenav_func(element) {
    const value = prompt("Insert a new function name");
    if (!value || all_the_functions.includes(value)) return;
    const link = document.getElementById(element.id);
    const oldName = link.innerText;
    link.innerText = value;
    send_results({ timestamp: Date.now(), event: 'func_rename', element: oldName.trim(), value: value });
}

function sleep(ms) { return new Promise(res => setTimeout(res, ms)); }

async function demo() {
    await sleep(1000);
    restore_graph_rename(myData);
}

async function restore(codeId) {
    await sleep(1000);
    if (typeof restore_graph_rename_after_rendering === 'function') {
        restore_graph_rename_after_rendering(codeId);
    }
}

function restore_graph_comments(data) {
    const downloadedData = typeof data === 'string' ? JSON.parse(data) : data;
    downloadedData.forEach(item => {
        if (item.event === 'comment') {
            const addr = item.element;
            const codeId = cfg_getBBbyAddress(addr);
            if (codeId) {
                cfg[codeId].asm = cfg[codeId].asm.replace(addr, `# ${item.value}\n${addr}`);
                cfg[codeId].label = cfg[codeId].label.replace(addr, `# ${item.value}\n${addr}`);
            }
        }
    });
    removeGraph();
    graphRender(-1);
}

function restore_graph_rename(data) {
    const downloadedData = typeof data === 'string' ? JSON.parse(data) : data;
    downloadedData.forEach(item => {
        if (item.event === 'rename') {
            const addr = item.element, value = item.value;
            listOfRenamedVariables.push(value);
            const locals = document.querySelectorAll(`code span.token.local`);
            locals.forEach(l => {
                const generic = l.querySelector('.token.generic');
                if (generic && generic.id === addr) {
                    generic.innerText = value;
                }
            });
        }
    });
    if (addr_to_zoom != 0) {
        scrollToAddress(addr_to_zoom, scrollEventsEnum.STR_XREF);
        obfuscate(cfg_getBBbyAddress(addr_to_zoom));
    }
}

function push_function_history(function_id, addr) {
    if (!function_id) function_id = func_to_download;
    let list = [];
    try { list = JSON.parse(localStorage.getItem('myFunctionHistory')) || []; } catch (e) { }
    list.push([function_id, addr]);
    localStorage.setItem('myFunctionHistory', JSON.stringify(list));
}

function pop_function_history() {
    let list = [];
    try { list = JSON.parse(localStorage.getItem('myFunctionHistory')) || []; } catch (e) { }
    if (!list.length) return null;
    const ret = list.pop();
    localStorage.setItem('myFunctionHistory', JSON.stringify(list));
    return ret;
}

function graphRender(codeId) {
    g = new dagreD3.graphlib.Graph().setGraph({});
    Object.keys(cfg).forEach(state => {
        let value = cfg[state];
        value.labelType = "html";
        value.label = `<pre><code id='${state}' class='language-nasm'>${value.asm}</code></pre>`;
        value.rx = value.ry = 5;
        g.setNode(state, value);
    });

    let binary_edges = {};
    const challId = parseInt(current_chall);
    if (current_chall === "first_chall" || challId === 1) binary_edges = first_binary_edges;
    else if (current_chall === "seventh_chall" || challId === 7) binary_edges = second_binary_edges;
    else if (current_chall === "fourth_chall" || challId === 4) binary_edges = fourth_binary_edges;

    cfg_edges.forEach(e => {
        let options = { label: "" };
        if (func_to_download in binary_edges) {
            let branch = binary_edges[func_to_download][e[0]];
            if (branch && 't' in branch && branch['t'] !== branch['f']) {
                if (e[1] === branch['t']) options.style = "stroke: #00ff00; stroke-width: 4px; fill: none;";
                else if (e[1] === branch['f']) options.style = "stroke: #f66; stroke-width: 4px; fill: none;";
            }
        }
        g.setEdge(e[0], e[1], options);
    });

    render = new dagreD3.render();
    let svg = d3.select("svg");
    let inner = svg.append("g");
    zoom = d3.zoom().on("zoom", () => inner.attr("transform", d3.event.transform));
    svg.call(zoom);
    render(inner, g);

    svg.attr('width', 1600).attr('height', 1024);
    restore(codeId);
    if (typeof myPrism === 'function') myPrism(codeId);
}

function rename(htmlElementToRename) {
    const inner = htmlElementToRename.innerHTML;
    let r = prompt("insert the new name (max 8 chars)");
    if (!r) return;
    if (r.length > 8) r = r.substring(0, 8);
    if (listOfRenamedVariables.includes(r)) { alert('Name already in use'); return; }
    listOfRenamedVariables.push(r);

    send_results({ timestamp: Date.now(), event: 'rename', element: htmlElementToRename.id, value: r });

    Object.keys(cfg).forEach(state => {
        const codes = document.querySelectorAll(`code[id="${state}"] a > span.token.local`);
        let changed = false;
        codes.forEach(c => {
            if (c.textContent === inner) {
                c.innerHTML = `<span id='${htmlElementToRename.id}' class='token generic' style='${state === bbCache ? "" : "filter:blur(8px)"}'>${r}</span>`;
                changed = true;
            }
        });
        if (changed) {
            const newAsm = document.querySelector(`code[id="${state}"]`).textContent;
            cfg[state].asm = newAsm;
            cfg[state].label = cfg[state].label.replace(inner, r); // basic replacement
        }
    });

    removeGraph();
    graphRender(bbCache);
}

function addCopyButtons() {
    // Target all code blocks including those inside the CFG graph
    const blocks = document.querySelectorAll("pre code, .node foreignObject code");

    blocks.forEach(code => {
        // Avoid duplicate buttons
        if (code.parentNode.classList.contains("code-container")) return;

        const wrapper = document.createElement("div");
        wrapper.classList.add("code-container");

        // Adjust insertion point
        code.parentNode.insertBefore(wrapper, code);
        wrapper.appendChild(code);

        const btn = document.createElement("button");
        btn.className = "copy-btn";
        btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-6"><path stroke-linecap="round" stroke-linejoin="round" d="M15.75 17.25v3.375c0 .621-.504 1.125-1.125 1.125h-9.75a1.125 1.125 0 0 1-1.125-1.125V7.875c0-.621.504-1.125 1.125-1.125H6.75a9.06 9.06 0 0 1 1.5.124m7.5 10.376h3.375c.621 0 1.125-.504 1.125-1.125V11.25c0-4.46-3.243-8.161-7.5-8.876a9.06 9.06 0 0 0-1.5-.124H9.375c-.621 0-1.125.504-1.125 1.125v3.5m7.5 10.375H9.375a1.125 1.125 0 0 1-1.125-1.125v-9.25m12 6.625v-1.875a3.375 3.375 0 0 0-3.375-3.375h-1.5a1.125 1.125 0 0 1-1.125-1.125v-1.5a3.375 3.375 0 0 0-3.375-3.375H9.75" /></svg>';
        btn.title = "Copy Code";
        wrapper.appendChild(btn);

        btn.addEventListener("click", (e) => {
            // Prevent D3 zoom/pan from triggering when clicking the copy button
            e.stopPropagation();
            e.preventDefault();

            copyToClipboard(code.innerText).then(() => {
                btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-6"><path stroke-linecap="round" stroke-linejoin="round" d="m4.5 12.75 6 6 9-13.5" /></svg>';
            });
        });
    });
}

function copyToClipboard(text) {
    if (!navigator.clipboard) {
        var textArea = document.createElement("textarea");
        textArea.value = text;
        textArea.style.position = "fixed";
        textArea.style.left = "-9999px";
        textArea.style.top = "0";
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        try { document.execCommand('copy'); } catch (err) { console.error('Fallback copy failed', err); }
        document.body.removeChild(textArea);
        return Promise.resolve();
    }
    return navigator.clipboard.writeText(text);
}